import numpy as np, os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
for n in (1,2,3):
    a=np.array(G[f'Demo pair {n} input']); H,W=a.shape
    cs=Counter(a.flatten().tolist()); bg=cs.most_common(1)[0][0]
    others={c:int((a==c).sum()) for c in set(a.flatten().tolist())-{bg}}
    print('demo',n,'bg',bg,dict(sorted(others.items())))
    ones=[c for c,k in others.items() if k==1]
    print('   single-count colors:',[(c,others[c]) for c in ones])

