import numpy as np
from scipy import ndimage
for n in (1,2,3):
    a=np.array(G[f'Demo pair {n} input']); bg=int(np.bincount(a.flatten().tolist()).argmax())
    print('--- demo',n,'bg',bg)
    for c in sorted(set(a.flatten().tolist())):
        if c==bg: continue
        lab,num=ndimage.label(a==c,structure=np.ones((3,3)))
        for i in range(1,num+1):
            pts=np.argwhere(lab==i)
            cy=min(pts[:,0]); cx=min(pts[:,1])
            sh=tuple(sorted([(int(p)-cy,int(q)-cx) for p,q in zip(pts[:,0],pts[:,1])]))
            sz=len(sh)
            rows={}
            for r,c_ in sh: rows.setdefault(r,set()).add(c_)
            print(f'   c={c} size={sz} top={min(pts[:,0])},{min(pts[:,1])} shape_rows={rows}')

